g = [list(map(int, input().split())) for _ in range(5)]
r = c = 0
while True:
    if g[r][c] == 2:
        g[r][c] = 9
        break
    g[r][c] = 9
    if c + 1 < 5 and g[r][c + 1] != 1:
        c += 1
    elif r + 1 < 5 and g[r + 1][c] != 1:
        r += 1
    else:
        break
for row in g:
    print(*row)
